def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    visited = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in visited:
                continue

            # Flood-fill one connected zero region.
            stack = [(r, c)]
            visited.add((r, c))
            region = []
            touches_edge = False
            border = set()
            while stack:
                x, y = stack.pop()
                region.append((x, y))
                if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                    touches_edge = True
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w:
                        if grid[nx][ny] == 0 and (nx, ny) not in visited:
                            visited.add((nx, ny))
                            stack.append((nx, ny))
                        elif grid[nx][ny] == 1:
                            border.add((nx, ny))

            if touches_edge or not border:
                continue

            # Paint enclosed zero area, leaving its center cell(s) as zero.
            r0 = min(x for x, y in region)
            r1 = max(x for x, y in region)
            c0 = min(y for x, y in region)
            c1 = max(y for x, y in region)
            mr0, mr1 = (r0 + r1) // 2, (r0 + r1 + 1) // 2
            mc0, mc1 = (c0 + c1) // 2, (c0 + c1 + 1) // 2
            for x, y in region:
                if not (mr0 <= x <= mr1 and mc0 <= y <= mc1):
                    out[x][y] = 3

            # Frame the bounding box of the adjacent outline.
            br0 = min(x for x, y in border)
            br1 = max(x for x, y in border)
            bc0 = min(y for x, y in border)
            bc1 = max(y for x, y in border)
            for x in range(max(0, br0 - 1), min(h, br1 + 2)):
                for y in range(max(0, bc0 - 1), min(w, bc1 + 2)):
                    if x in (br0 - 1, br1 + 1) or y in (bc0 - 1, bc1 + 1):
                        if grid[x][y] == 0:
                            out[x][y] = 2

    return out
